INSERT INTO pecas (slug,nome,artesao,territorio,tecnica,categoria,tipo,preco,desconto,disponibilidade,prazo_producao_dias,historia,imagem,avaliacao,total_avaliacoes,situacao,inativado_em,ordem_catalogo,texto_busca) VALUES ('leao-imperial-de-tracunhaem', 'Leão Imperial de Tracunhaém', 'mestre-nuca', 'Mata Norte', 'Cerâmica & Barro', 'Decoração & Arte', 'Esculturas & Bonecos', 1250, 0, 'unica', NULL, ARRAY['O Leão de Tracunhaém é mais que uma peça decorativa; é o guardião simbólico das casas pernambucanas. Criado originalmente pelo mestre de memórias rurais, esta peça continua o legado das jubas encaracoladas moldadas com facas simples na argila viva.', 'Cada linha de sua cabeleira é esculpida uma a uma, num ritual de paciência que dura dias antes de ir ao forno a lenha tradicional. Uma peça autêntica que carrega o carimbo de autenticidade do território de Tracunhaém.']::text[], '/fotos/leao-imperial.svg', 4.9, 27, 'publicada', NULL, 1, 'leao imperial de tracunhaem mestre-nuca mestre nuca (sucessor) mata norte ceramica & barro decoracao & arte esculturas & bonecos');
INSERT INTO pecas (slug,nome,artesao,territorio,tecnica,categoria,tipo,preco,desconto,disponibilidade,prazo_producao_dias,historia,imagem,avaliacao,total_avaliacoes,situacao,inativado_em,ordem_catalogo,texto_busca) VALUES ('toalha-renascenca-florescer', 'Toalha Renascença Florescer', 'maria-de-caruaru', 'Cariri', 'Bordado & Renda (Renascença)', 'Casa & Mesa', 'Toalhas & Rendas', 850, 0, 'encomenda', 21, ARRAY['A renda renascença chegou ao Cariri pernambucano no início do século passado e virou ofício de família. O ponto é feito com lacê e agulha, unindo desenhos que nascem no papel e viram flor no tecido.', 'Cada toalha leva cerca de três semanas de trabalho. O prazo não é atraso: é o tempo que a técnica exige.']::text[], '/fotos/toalha-renascenca.svg', 5, 12, 'publicada', NULL, 2, 'toalha renascenca florescer maria-de-caruaru maria de caruaru cariri bordado & renda (renascenca) casa & mesa toalhas & rendas');
INSERT INTO pecas (slug,nome,artesao,territorio,tecnica,categoria,tipo,preco,desconto,disponibilidade,prazo_producao_dias,historia,imagem,avaliacao,total_avaliacoes,situacao,inativado_em,ordem_catalogo,texto_busca) VALUES ('gibao-de-couro-de-sertao', 'Gibão de Couro de Sertão', 'ze-do-cariri', 'Pajeú', 'Couro Autoral', 'Vestuário & Acessórios', 'Couro: Bolsas, Cintos & Gibões', 490, 0, 'disponivel', NULL, ARRAY['O gibão nasceu como armadura do vaqueiro contra a caatinga. Hoje o couro curtido à moda antiga vira peça de vestir que guarda a memória do sertão.']::text[], '/fotos/gibao-couro.svg', 4.7, 9, 'publicada', NULL, 3, 'gibao de couro de sertao ze-do-cariri artesao ze do cariri pajeu couro autoral vestuario & acessorios couro: bolsas, cintos & giboes');
INSERT INTO pecas (slug,nome,artesao,territorio,tecnica,categoria,tipo,preco,desconto,disponibilidade,prazo_producao_dias,historia,imagem,avaliacao,total_avaliacoes,situacao,inativado_em,ordem_catalogo,texto_busca) VALUES ('sanfoneiro-em-imburana', 'Sanfoneiro em Imburana', 'mestre-amaro', 'Petrolina', 'Escultura em Madeira', 'Decoração & Arte', 'Esculturas & Bonecos', 780, 0, 'disponivel', NULL, ARRAY['Entalhado em imburana, madeira leve e perfumada do sertão, o sanfoneiro é figura obrigatória do São João. A peça sai de um único bloco, sem emendas.']::text[], '/fotos/sanfoneiro-imburana.svg', 4.8, 15, 'publicada', NULL, 4, 'sanfoneiro em imburana mestre-amaro mestre amaro petrolina escultura em madeira decoracao & arte esculturas & bonecos');
INSERT INTO pecas (slug,nome,artesao,territorio,tecnica,categoria,tipo,preco,desconto,disponibilidade,prazo_producao_dias,historia,imagem,avaliacao,total_avaliacoes,situacao,inativado_em,ordem_catalogo,texto_busca) VALUES ('jarra-de-ceramica-cabocla', 'Jarra de Cerâmica Cabocla', 'dona-bia-do-ipojuca', 'Vale do Ipojuca', 'Cerâmica & Barro', 'Casa & Mesa', 'Jarras & Vasos', 350, 0, 'disponivel', NULL, ARRAY['Pintada à mão com pigmentos naturais, a jarra cabocla reúne cenas de feira, procissão e forró em faixas que dão a volta na peça.']::text[], '/fotos/jarra-cabocla.svg', 4.6, 21, 'publicada', NULL, 5, 'jarra de ceramica cabocla dona-bia-do-ipojuca dona bia do ipojuca vale do ipojuca ceramica & barro casa & mesa jarras & vasos');
INSERT INTO pecas (slug,nome,artesao,territorio,tecnica,categoria,tipo,preco,desconto,disponibilidade,prazo_producao_dias,historia,imagem,avaliacao,total_avaliacoes,situacao,inativado_em,ordem_catalogo,texto_busca) VALUES ('painel-xilogravura-sertaneja', 'Painel Xilogravura Sertaneja', 'mestre-dila', 'Caruaru', 'Xilogravura', 'Decoração & Arte', 'Gravuras & Cordéis', 950, 0, 'unica', NULL, ARRAY['A matriz é entalhada na madeira e impressa à mão, uma folha por vez. Cada tiragem carrega marcas próprias: não existem dois painéis iguais.']::text[], '/fotos/painel-xilogravura.svg', 5, 8, 'publicada', NULL, 6, 'painel xilogravura sertaneja mestre-dila mestre dila caruaru xilogravura decoracao & arte gravuras & cordeis');
